Here is the commit message:
wifi: rsi: Don't default to -EOPNOTSUPP in
 rsi_mac80211_config

This triggers a WARN_ON in ieee80211_hw_conf_init and isn't the expected
behavior from the driver - other drivers default to 0 too.

Fixes: 0a44dfc07074 ("wifi: mac80211: simplify non-chanctx drivers")
Signed-off-by: Sebastian Krzyszkowiak <sebastian.krzyszkowiak@puri.sm>
Link: https://patch.msgid.link/20260221-rsi-config-ret-v1-1-9a8f805e2f31@puri.sm
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The function `rsi_mac80211_config` in the RSI driver incorrectly defaulted to returning `-EOPNOTSUPP` for unhandled configuration changes, which triggered a WARN_ON in `ieee80211_hw_conf_init` because mac80211 expects a zero return when no change is made or the operation is simply not applicable.

Here is the patch:
  */
 static int rsi_mac80211_config(struct ieee80211_hw *hw,
 			       int radio_idx,
 			       u32 changed)
 {
 	struct rsi_hw *adapter = hw->priv;
 	struct rsi_common *common = adapter->priv;
 	struct ieee80211_conf *conf = &hw->conf;
-	int status = -EOPNOTSUPP;
+	int status = 0;

 	mutex_lock(&common->mutex);

 	if (changed & IEEE80211_CONF_CHANGE_CHANNEL)
 		status = rsi_channel_change(hw);

 	/* tx power */
 	if (changed & IEEE80211_CONF_CHANGE_POWER) {
 		rsi_dbg(INFO_ZONE, "%s: Configuring Power\n", __func__);
 		status = rsi_config_power(hw);
 	}

 	/* Power save parameters */
 	if ((changed & IEEE80211_CONF_CHANGE_PS) &&
 	    !common->mac_ops_resumed) {
 		struct ieee80211_vif *vif, *sta_vif = NULL;
 		unsigned long flags;
 		int i, set_ps = 1;

 		for (i = 0; i < RSI_MAX_VIFS; i++) {
 			vif = adapter->vifs[i];
 			if (!vif)
 				continue;
 			/* Don't go to power save if AP vap exists */
 			if ((vif->type == NL80211_IFTYPE_AP) ||
 			    (vif->type == NL80211_IFTYPE_P2P_GO)) {
 				set_ps = 0;
 				break;
 			}
 			if ((vif->type == NL80211_IFTYPE_STATION ||
 			     vif->type == NL80211_IFTYPE_P2P_CLIENT) &&
 			    (!sta_vif || vif->cfg.assoc))
 				sta_vif = vif;
 		}
 		if (set_ps && sta_vif) {
 			spin_lock_irqsave(&adapter->ps_lock, flags);
 			if (conf->flags & IEEE80211_CONF_PS)
 				rsi_enable_ps(adapter, sta_vif);
 			else
 				rsi_disable_ps(adapter, sta_vif);
 			spin_unlock_irqrestore(&adapter->ps_lock, flags);
 		}
 	}

 	/* RTS threshold */
 	if (changed & WIPHY_PARAM_RTS_THRESHOLD) {
 		rsi_dbg(INFO_ZONE, "RTS threshold\n");
 		if ((common->rts_threshold) <= IEEE80211_MAX_RTS_THRESHOLD) {
 			rsi_dbg(INFO_ZONE,
 				"%s: Sending vap updates....\n", __func__);
 			status = rsi_send_vap_dynamic_update(common);
 		}
 	}
 	mutex_unlock(&common->mutex);

 	return status;
 }



